mapper.select:
Select 그룹코드 as groupCode -- 그룹코드 ,코드분류 as codeGb -- 코드분류 ,비밀번호 as password -- 비밀번호 ,그룹설명 as groupName -- 그룹설명 ,날짜 as date -- 날짜 ,금액 as amt -- 금액 ,비고 as cnte -- 비고 ,성도코드1 as nmNo1 -- 성도코드1 ,이름1 as name1 -- 이름1 ,성도코드2 as nmNo2 -- 성도코드2 ,이름2 as name2 -- 이름2 ,성도코드3 as nmNo3 -- 성도코드3 ,이름3 as name3 -- 이름3 ,sns as sns -- sns ,은행 as bank -- 은행 ,계좌번호 as bankNo -- 계좌번호 ,핸드폰번호 as handNo -- 핸드폰번호 ,년도 as year -- year ,workcd as workcd -- workcd From 지출_groupInfo as Grb WHERE 1 = 1
AND Grb.코드분류 = #{codeGb}
AND Grb.이름1 like '%'||#{name1}||'%'
AND Grb.그룹설명 like '%'||#{groupName}||'%'
AND Grb.년도 = #{year}
AND Grb.workcd = #{workcd}
AND Grb.날짜 >= #{fmDate}
AND Grb.날짜 <= #{toDate}
order by 그룹코드

mapper.update:
update 지출_groupInfo Set 그룹코드 = #{groupCode} -- 그룹코드 , 코드분류 = #{codeGb} -- 코드분류
, 비밀번호 = #{password} -- 비밀번호
, 그룹설명 = #{groupName} -- 그룹설명 , 날짜 = #{date} -- 날짜 , 금액 = #{amt} -- 금액 , 비고 = #{cnte} -- 비고 , 성도코드1 = #{nmNo1} -- 성도코드1 , 이름1 = #{name1} -- 이름1 , 성도코드2 = #{nmNo2} -- 성도코드2 , 이름2 = #{name2} -- 이름2 , 성도코드3 = #{nmNo3} -- 성도코드3 , 이름3 = #{name3} -- 이름3 , sns = #{sns} -- sns , 은행 = #{bank} -- 은행 , 계좌번호 = #{bankNo} -- 계좌번호 , 핸드폰번호 = #{handNo} -- 핸드폰번호 , 년도 = #{year} -- year , workcd = #{workcd} -- workcd where 그룹코드 = #{groupCode}
